/* The embedded built-in fonts (arrays generated by tools/embed.c at build time). */
#ifndef EXHAUST_FONTS_DATA_H
#define EXHAUST_FONTS_DATA_H
#include <stddef.h>
#include "exhaust_text.h"

typedef struct ExEmbeddedFont {
    const unsigned char *data;
    size_t size;
} ExEmbeddedFont;

/* Returns the embedded font file for a built-in font, or {NULL, 0}. */
ExEmbeddedFont ex_embedded_font(ExBuiltinFont which);
#endif
